}

/* ---------- uncertainty wedge ---------- */
function wedge(apexes, dLo, dHi) {
  var xLo = xOfD(dLo), xHi = xOfD(dHi);
  for (var i = 0; i < apexes.length; i++) {
    var a = apexes[i];
    gWedge.polygon(a[0] + ',' + a[1] + ' ' + xLo + ',' + SEA_Y + ' ' + xHi + ',' + SEA_Y)
      .fill({ color: ORANGE, opacity: 0.22 }).stroke({ color: ORANGE, width: 1.5, opacity: 0.55 });
  }
  var bar = gWedge.line(xLo, SEA_Y, xHi, SEA_Y).stroke({ color: ORANGE, width: 8, opacity: 0.85, linecap: 'butt' });
  gWedge.line(xLo, SEA_Y - 11, xLo, SEA_Y + 11).stroke({ color: ORANGE, width: 3 });
  gWedge.line(xHi, SEA_Y - 11, xHi, SEA_Y + 11).stroke({ color: ORANGE, width: 3 });
  hov(bar, 'Possible boat positions for the measured angle ±' + state.err + '°',
    'Angular error becomes depth error',
    'Every position inside the wedge is consistent with the measurement. The wedge length grows roughly with the square of the distance and shrinks in proportion to the known length (h or t) — the depth-uncertainty law that also governs stereo vision.');
}

/* ---------- mode 1: single observer ---------- */
function single(xB) {
  var h = state.h, d = state.d, ey = eyeYpix(h);
  var aDeg = dg(Math.atan(h / d));
  var lines = ['Single observer — height + horizon',
               'h = ' + h + ' m,\u2003\u03B1 = ' + aDeg.toFixed(2) + '\u00B0',
               'd = h / tan \u03B1 = ' + Math.round(d) + ' m'];

  if (state.err > 0) {
    var dLo = h / Math.tan(rad(aDeg + state.err));
    var aHi = Math.max(aDeg - state.err, 0.004);
    var dHi = h / Math.tan(rad(aHi));
    wedge([[EX, ey]], dLo, dHi);
    lines.push('\u00B1' + state.err + '\u00B0 \u2192 d \u2208 [' + Math.round(dLo) + ', ' +
      (dHi > 4000 ? '\u221E' : Math.round(dHi)) + '] m');
  }

  var ray = gGeo.line(EX + 18, ey, 655, ey).stroke({ color: '#000', width: 3 });
  hov(ray, 'Horizontal reference: the line of sight to the horizon',
    'The horizon is your level',
    'The line to the horizon is essentially horizontal, so it gives a free horizontal reference in the sky. The angle the boat lies below it is the depression angle \u03B1.');

  var sight = gGeo.line(EX, ey, xB, SEA_Y).stroke({ color: '#000', width: 3 });
  hov(sight, 'Line of sight to the boat', 'Line of sight',
    'Together with the horizon ray and the vertical height h this closes a right triangle whose legs are h and d, so tan \u03B1 = h / d.');

  var hl = gGeo.line(EX, ey + 17, EX, SEA_Y).stroke({ color: '#000', width: 3 });
  hov(hl, 'Known height h = ' + h + ' m', 'The known length',
    'h is the one measured length in the whole construction. Without it the angle \u03B1 fixes only a direction, never a distance — raise h and the same boat produces a bigger, easier-to-measure \u03B1.');

  gGeo.polygon(EX + ',' + (SEA_Y - 18) + ' ' + (EX + 18) + ',' + (SEA_Y - 18) + ' ' + (EX + 18) + ',' + SEA_Y + ' ' + EX + ',' + SEA_Y)
    .fill('#c9c9c9').stroke({ color: '#000', width: 2 });

  var dl = gGeo.line(EX, SEA_Y, xB, SEA_Y).stroke({ color: '#000', width: 3.5 });
  hov(dl, 'd = the unknown horizontal distance', 'The unknown d',
    'This horizontal leg is what we want. Solving the right triangle gives d = h / tan \u03B1.');

  var dist = Math.hypot(xB - EX, SEA_Y - ey);
  var r1 = Math.min(92, 0.42 * dist);
  var A1 = arcInfo(EX, ey, r1, 1, 0, xB - EX, SEA_Y - ey);
  var arc1 = gGeo.path(A1.path).fill('none').stroke({ color: '#000', width: 2.5 });
  hov(arc1, 'Depression angle \u03B1 = ' + aDeg.toFixed(2) + '\u00B0', 'Depression angle \u03B1',
    'Measured between the horizon ray and the line of sight to the boat. It is the only quantity the observer actually measures.');
  lab(gLab, EX + (r1 + 30) * Math.cos(rad(A1.mid)), ey + (r1 + 30) * Math.sin(rad(A1.mid)), '\u03B1');

  var r2 = Math.min(58, 0.28 * dist);
  var A2 = arcInfo(xB, SEA_Y, r2, -1, 0, EX - xB, ey - SEA_Y);
  gGeo.path(A2.path).fill('none').stroke({ color: '#000', width: 2.5 });
  lab(gLab, xB + (r2 + 26) * Math.cos(rad(A2.mid)), SEA_Y + (r2 + 26) * Math.sin(rad(A2.mid)), '\u03B1');

  var eye = gGeo.circle(34).center(EX, ey).fill('#fff').stroke({ color: '#000', width: 3.5 });
  hov(eye, "Observer's eye, h = " + h + ' m above the water', 'The observer',
    'One eye, one known height, one measured angle. That is enough to turn a direction into a metric distance.');

  lab(gLab, EX - 28, (ey + SEA_Y) / 2, 'h');
  lab(gLab, (EX + xB) / 2, SEA_Y + 32, 'd?');
  return lines;
}

/* ---------- mode 2: two observers ---------- */
function dual(xB) {
  var t = state.t, d = state.d;
  var tp = 48 + 120 * Math.sqrt((t - 5) / 245);
  var ux = 0.26, uy = 0.966;
  var Bx = 320, By = 236, Ax = Bx - tp * ux, Ay = By - tp * uy;
  var gam = 2 * Math.atan((t / 2) / d), gDeg = dg(gam), aDeg = (180 - gDeg) / 2;

  var lines = ['Two observers — known baseline t',
               't = ' + t + ' m,\u2003\u03B1 = \u03B2 = ' + aDeg.toFixed(2) + '\u00B0',
               'parallax \u03B3 = 180\u00B0\u2212\u03B1\u2212\u03B2 = ' + gDeg.toFixed(2) + '\u00B0',
               'd = (t/2)/tan(\u03B3/2) = ' + Math.round(d) + ' m'];

  if (state.err > 0) {
    var gHi = gam + 2 * rad(state.err), gLo = gam - 2 * rad(state.err);
    var dLo = (t / 2) / Math.tan(gHi / 2);
    var dHi = gLo > 0.00002 ? (t / 2) / Math.tan(gLo / 2) : 1e6;
    wedge([[Ax, Ay], [Bx, By]], dLo, dHi);
    lines.push('\u00B1' + state.err + '\u00B0 \u2192 d \u2208 [' + Math.round(dLo) + ', ' +
      (dHi > 4000 ? '\u221E' : Math.round(dHi)) + '] m');
  }

  var base = gGeo.line(Ax, Ay, Bx, By).stroke({ color: '#000', width: 3 });
  hov(base, 'Known separation t = ' + t + ' m', 'The baseline t',
    'The distance between the two viewpoints replaces the known height. A wider baseline makes the two sight lines cross at a larger angle, so the intersection — the boat — is far better localised. This is why eyes and stereo cameras are set apart.');

  var s = 16, px = Ax + 0.62 * tp * ux, py = Ay + 0.62 * tp * uy, nx = uy, ny = -ux;
  gGeo.polygon(px + ',' + py + ' ' + (px + s * ux) + ',' + (py + s * uy) + ' ' +
    (px + s * ux + s * nx) + ',' + (py + s * uy + s * ny) + ' ' + (px + s * nx) + ',' + (py + s * ny))
    .fill('#c9c9c9').stroke({ color: '#000', width: 2 });

  var sA = gGeo.line(Ax, Ay, xB, SEA_Y).stroke({ color: '#000', width: 3 });
  var sB = gGeo.line(Bx, By, xB, SEA_Y).stroke({ color: '#000', width: 3 });
  hov(sA, 'Bearing measured from the upper observer', 'Two bearings, one point',
    'Each observer measures only a direction. Two directions from two known points intersect at exactly one place — no horizon and no absolute height required.');
  hov(sB, 'Bearing measured from the lower observer', 'Two bearings, one point',
    'Each observer measures only a direction. Two directions from two known points intersect at exactly one place — no horizon and no absolute height required.');

  var rA = Math.min(70, 0.55 * tp);
  var AA = arcInfo(Ax, Ay, rA, xB - Ax, SEA_Y - Ay, Bx - Ax, By - Ay);
  var arcA = gGeo.path(AA.path).fill('none').stroke({ color: '#000', width: 2.5 });
  hov(arcA, '\u03B1 = ' + aDeg.toFixed(2) + '\u00B0 (baseline to boat)', 'Angle \u03B1',
    'Measured at the upper observer between the baseline and the sight line to the boat.');
  lab(gLab, Ax + (rA + 26) * Math.cos(rad(AA.mid)), Ay + (rA + 26) * Math.sin(rad(AA.mid)), '\u03B1');

  var rB = Math.min(60, 0.5 * tp);
  var AB = arcInfo(Bx, By, rB, Ax - Bx, Ay - By, xB - Bx, SEA_Y - By);
  var arcB = gGeo.path(AB.path).fill('none').stroke({ color: '#000', width: 2.5 });
  hov(arcB, '\u03B2 = ' + aDeg.toFixed(2) + '\u00B0 (baseline to boat)', 'Angle \u03B2',
    'Measured at the lower observer. The parallax \u03B3 = 180\u00B0\u2212\u03B1\u2212\u03B2 is the disparity: it collapses to zero for a very distant boat.');
  lab(gLab, Bx + (rB + 26) * Math.cos(rad(AB.mid)), By + (rB + 26) * Math.sin(rad(AB.mid)), '\u03B2');

  var oA = gGeo.circle(34).center(Ax, Ay).fill('#fff').stroke({ color: '#000', width: 3.5 });
  var oB = gGeo.circle(34).center(Bx, By).fill('#fff').stroke({ color: '#000', width: 3.5 });
  hov(oA, 'Observer A', 'Viewpoint A', 'One of the two viewpoints. Only their separation t has to be known.');
  hov(oB, 'Observer B', 'Viewpoint B', 'One of the two viewpoints. Only their separation t has to be known.');

  var mx = (Ax + Bx) / 2, my = (Ay + By) / 2;
  lab(gLab, mx - 27 * nx, my - 27 * ny, 't');
  var vx = xB - Ax, vy = SEA_Y - Ay, vl = Math.hypot(vx, vy);
  lab(gLab, Ax + 0.52 * vx + 26 * (vy / vl), Ay + 0.52 * vy - 26 * (vx / vl), 'd?');
  return lines;
}

/* ---------- readout ---------- */
function readout(lines) {
  var bw = 330, bh = 16 + lines.length * 25, bx = W - bw - 22, by = 16;
  var box = gRead.rect(bw, bh).move(bx, by).radius(5)
    .fill({ color: '#ffffff', opacity: 0.93 }).stroke({ color: '#777', width: 1.5 });
  hov(box, 'Measured angles and the distance inferred from them', 'Reading the numbers',
    'The top line is what the observer knows (a length), the middle lines are what is measured (angles), and the last line is the inferred distance — plus its uncertainty when the angles are imperfect.');
  for (var i = 0; i < lines.length; i++) {
    gRead.plain(lines[i]).font({ family: 'Georgia,"Times New Roman",serif', size: 16, anchor: 'start' })
      .attr({ x: bx + 14, y: by + 24 + i * 25, fill: i === 0 ? '#333' : '#000', 'dominant-baseline': 'middle' });
  }
}

/* ---------- render ---------- */
function render() {
  gBg.clear(); gWedge.clear(); gGeo.clear(); gBoat.clear(); gLab.clear(); gRead.clear();
  var apexX, apexY, leftX, shoreX;
  if (!state.mode2) { apexX = EX; apexY = eyeYpix(state.h) - 2; leftX = 92; shoreX = 340; }
  else { apexX = 230; apexY = 26; leftX = 80; shoreX = 350; }
  scene(apexX, apexY, leftX, shoreX);
  var xB = xOfD(state.d);
  var lines = state.mode2 ? dual(xB) : single(xB);
  boat(xB);
  readout(lines);
}

/* ---------- controls ---------- */
function syncDisabled() {
  document.getElementById('observerHeightInput').disabled = state.mode2;
  document.getElementById('baselineInput').disabled = !state.mode2;
  document.getElementById('hLab').style.opacity = state.mode2 ? 0.4 : 1;
  document.getElementById('tLab').style.opacity = state.mode2 ? 1 : 0.4;
}
function toggle_methodToggle(on) { state.mode2 = !!on; syncDisabled(); render(); }
function update_observerHeight(v) { state.h = v; render(); }
function update_baseline(v) { state.t = v; render(); }
function update_boatDistance(v) { state.d = v; render(); }
function update_angleError(v) { state.err = v; render(); }

/* ---------- demo steps ---------- */
var steps = [
  { title: 'The question: how far is the boat?', narration: 'An observer on a cliff sees a sailboat. The only unknown is d, the horizontal distance; everything else must come from angles.', state: { methodToggle: 'Single observer', observerHeight: 25, boatDistance: 600, angleError: 0 } },
  { title: 'The horizon gives a horizontal reference', narration: 'The line to the horizon is nearly horizontal, so \u03B1 below it is the depression angle. The same \u03B1 reappears at the boat as an alternate angle, closing a right triangle with legs h and d.', state: { methodToggle: 'Single observer', observerHeight: 25, boatDistance: 600, angleError: 0 } },
  { title: 'Height sets the scale: d = h / tan \u03B1', narration: 'Raise the observer and \u03B1 grows for the same boat. Height converts a measured angle into a metric distance \u2014 without a known h, \u03B1 alone tells you nothing.', state: { methodToggle: 'Single observer', observerHeight: 90, boatDistance: 600, angleError: 0 } },
  { title: 'Far boats squeeze the angle', narration: 'Push the boat out to sea: \u03B1 collapses toward the horizon. Distant objects differ by a fraction of a degree, which is why far depth is hard to measure.', state: { methodToggle: 'Single observer', observerHeight: 25, boatDistance: 2600, angleError: 0 } },
  { title: 'Swap the known height for a known baseline', narration: 'Two observers a distance t apart each measure a bearing, \u03B1 and \u03B2. The boat lies where the sight lines cross \u2014 no horizon, no height needed.', state: { methodToggle: 'Two observers', baseline: 60, boatDistance: 600, angleError: 0 } },
  { title: 'A wider baseline sharpens the fix', narration: 'Increase t and the sight lines cross at a larger angle, so the intersection is far better localised. This is precisely why eyes \u2014 and stereo cameras \u2014 are set apart.', state: { methodToggle: 'Two observers', baseline: 220, boatDistance: 600, angleError: 0 } },
  { title: 'Angular error becomes depth error', narration: 'Add a small error to each angle and watch the wedge at the boat. The same error is tolerable up close but explodes far away, and shrinks again when h or t is large.', state: { methodToggle: 'Two observers', baseline: 60, boatDistance: 2000, angleError: 1 } }
];
var cur = 0;

function setSlider(id, v) {
  var i = document.getElementById(id + 'Input'); if (i) i.value = v;
  var o = document.getElementById(id + 'Val'); if (o) o.value = v;
}
function applyState(st) {
  if ('methodToggle' in st) {
    var on = /Two/.test(st.methodToggle);
    document.getElementById('methodToggleInput').checked = on;
    state.mode2 = on;
  }
  if ('observerHeight' in st) { setSlider('observerHeight', st.observerHeight); state.h = +st.observerHeight; }
  if ('baseline' in st) { setSlider('baseline', st.baseline); state.t = +st.baseline; }
  if ('boatDistance' in st) { setSlider('boatDistance', st.boatDistance); state.d = +st.boatDistance; }
  if ('angleError' in st) { setSlider('angleError', st.angleError); state.err = +st.angleError; }
  syncDisabled();
  render();
}
function gotoStep(i) {
  cur = clamp(i, 0, steps.length - 1);
  var s = steps[cur];
  document.getElementById('demoNarration').innerHTML = '<b>' + s.title + '</b><br>' + s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
  applyState(s.state);
}
function prevStep() { gotoStep(cur - 1); }
function nextStep() { gotoStep(cur + 1); }

gotoStep(0);
window.__markRendered();
// @FIGURE_CODE_END

