// @FIGURE_CODE_BEGIN
var W = 1000, H = 660, HOR = 277, GY = 478, GX = 175;
var SEA = '#5CF5E2', LAND = '#C4820C', CLIFF = '#8A4A07', ORANGE = '#F04A10', INK = '#000';
var FA = 0.55;                       // fraction of baseline from A to the foot of the perpendicular
var SERIF = 'Georgia,"Times New Roman",serif';

var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var gBg = draw.group(), gWedge = draw.group(), gGeo = draw.group(),
    gBoat = draw.group(), gLab = draw.group(), gPanel = draw.group(), gFrame = draw.group();
gFrame.rect(W - 7, H - 7).move(3.5, 3.5).fill('none').stroke({ color: INK, width: 7 });

var state = { mode2: false, L: 40, d: 600, err: 0 };

/* ───────── helpers ───────── */
function rad(a) { return a * Math.PI / 180; }
function dg(r) { return r * 180 / Math.PI; }
function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function cot(deg) { return 1 / Math.tan(rad(deg)); }

function hpxOf(L) { return 130 + 250 * Math.pow(clamp((L - 5) / 245, 0, 1), 0.25); }
function dpxOf(d) { return 300 + 390 * Math.pow(clamp((d - 50) / 2950, 0, 1), 0.45); }
function LtOf(t) { return 150 + 190 * Math.sqrt(clamp((t - 5) / 245, 0, 1)); }
function LdOf(d) { return 280 + 380 * Math.pow(clamp((d - 50) / 2950, 0, 1), 0.45); }

function hov(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (title) el.on('click', function () { showPopup(title, body); });
  return el;
}

function lab(x, y, s, size, anchor) {
  var t = gLab.plain(s).font({ family: SERIF, size: size || 34, anchor: anchor || 'middle', style: 'italic' });
  t.attr({
    x: x, y: y, 'dominant-baseline': 'middle', fill: INK,
    'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 6, 'stroke-linejoin': 'round'
  });
  return t;
}

function hit(x1, y1, x2, y2, tip, title, body) {
  var e = gGeo.line(x1, y1, x2, y2).stroke({ color: '#000', width: 22, opacity: 0 })
    .attr('pointer-events', 'stroke');
  return hov(e, tip, title, body);
}

function smooth(pts) {
  var d = 'M' + pts[0][0] + ',' + pts[0][1], n = pts.length;
  for (var i = 0; i < n - 1; i++) {
    var p0 = pts[i - 1 < 0 ? 0 : i - 1], p1 = pts[i], p2 = pts[i + 1], p3 = pts[i + 2 > n - 1 ? n - 1 : i + 2];
    d += ' C' + (p1[0] + (p2[0] - p0[0]) / 6) + ',' + (p1[1] + (p2[1] - p0[1]) / 6) + ' ' +
         (p2[0] - (p3[0] - p1[0]) / 6) + ',' + (p2[1] - (p3[1] - p1[1]) / 6) + ' ' + p2[0] + ',' + p2[1];
  }
  return d;
}

function arcInfo(cx, cy, r, ax, ay, bx, by) {
  var a0 = dg(Math.atan2(ay, ax)), a1 = dg(Math.atan2(by, bx));
  var diff = ((a1 - a0 + 540) % 360) - 180, t1 = a0 + diff;
  var x0 = cx + r * Math.cos(rad(a0)), y0 = cy + r * Math.sin(rad(a0));
  var x1 = cx + r * Math.cos(rad(t1)), y1 = cy + r * Math.sin(rad(t1));
  return {
    path: 'M' + x0 + ',' + y0 + ' A' + r + ',' + r + ' 0 0 ' + (diff > 0 ? 1 : 0) + ' ' + x1 + ',' + y1,
    mid: a0 + diff / 2
  };
}

/* ───────── boat ───────── */
function boat(x, y) {
  var g = gBoat.group().attr('transform', 'translate(' + x + ',' + y + ')');
  g.path('M-34,-6 L34,-6 C29,8 18,14 0,14 C-18,14 -29,8 -34,-6 Z')
    .fill('#fff').stroke({ color: INK, width: 3, linejoin: 'round' });
  g.line(-32, -2, 32, -2).stroke({ color: INK, width: 2.4 });
  g.line(4, -8, 7, -76).stroke({ color: INK, width: 3, linecap: 'round' });
  g.polygon('1,-72 1,-13 -31,-13').fill('#fff').stroke({ color: INK, width: 3, linejoin: 'round' });
  g.polygon('11,-62 11,-15 32,-15').fill('#fff').stroke({ color: INK, width: 3, linejoin: 'round' });
  hov(g, 'Boat — true distance d = ' + state.d + ' m', 'The unknown',
    'The boat cannot be reached, so its distance must be built out of angles. The slider sets the truth; the readout shows what an observer could infer from the measured angle(s) and the one known length.');
}

/* ───────── shared scenery ───────── */
function sky() {
  gBg.rect(W, H).fill('#fff');
  gBg.rect(W, H - HOR).move(0, HOR).fill(SEA);
}
function coastline(pts) {
  var cd = smooth(pts);
  gBg.path(cd + ' L0,' + H + ' L0,' + HOR + ' Z').fill(LAND).stroke('none');
  gBg.path(cd).fill('none').stroke({ color: INK, width: 4, linecap: 'round' });
}
function horizon() {
  var l = gBg.line(0, HOR, W, HOR).stroke({ color: INK, width: 3.5 });
  hov(l, 'Horizon — the sky/sea boundary', 'The horizon',
    'A sight line to the horizon is essentially horizontal, which is what gives the single observer a free horizontal reference to measure the depression angle α against.');
}

/* ───────── uncertainty wedge ───────── */
function wedgeBar(p1, p2, apexes) {
  for (var i = 0; i < apexes.length; i++) {
    gWedge.polygon(apexes[i][0] + ',' + apexes[i][1] + ' ' + p1[0] + ',' + p1[1] + ' ' + p2[0] + ',' + p2[1])
      .fill({ color: ORANGE, opacity: 0.20 }).stroke({ color: ORANGE, width: 1.4, opacity: 0.5 });
  }
  var bar = gWedge.line(p1[0], p1[1], p2[0], p2[1])
    .stroke({ color: ORANGE, width: 9, opacity: 0.9, linecap: 'butt' });
  hov(bar, 'Possible boat positions for the measured angle ±' + state.err + '°',
    'Angle error becomes distance error',
    'Every point in the orange wedge fits the measurement. Its length grows roughly with the square of the distance and shrinks in proportion to the known length h or t — the precision law of every angle-based rangefinder, including stereo vision.');
}

/* ───────── mode A: height + horizon ───────── */
function renderA() {
  var L = state.L, d = state.d, e = state.err;
  var hp = hpxOf(L), eY = GY - hp, bx = GX + dpxOf(d);
  var alpha = dg(Math.atan(L / d));

  sky();
  coastline([[210, HOR], [248, 316], [224, 364], [292, 410], [270, 460], [344, 512], [380, 572], [424, 626], [442, 660]]);
  horizon();

  /* cliff with the eye at its apex */
  var apexY = eY + 8, base = 650, Ht = base - apexY;
  var ks = [0, 0.14, 0.28, 0.42, 0.56, 0.70, 0.84, 0.93, 1],
      wl = [0, 16, -12, 18, -10, 20, -8, 10, 0], wr = [0, -14, 16, -10, 18, -12, 14, 8, 0];
  var pts = [], i, k;
  for (i = 0; i < ks.length; i++) { k = ks[i]; pts.push([GX - (150 * (1 - k) + wl[i] * (1 - k)), base - k * Ht]); }
  for (i = ks.length - 2; i >= 0; i--) { k = ks[i]; pts.push([GX + (158 * (1 - k) + wr[i] * (1 - k)), base - k * Ht]); }
  var cliff = gBg.path(smooth(pts) + ' Z').fill(CLIFF).stroke({ color: INK, width: 4, linejoin: 'round' });
  hov(cliff, 'The cliff — it supplies the known height h', 'Where the known length comes from',
    'The cliff is not decoration: its height above the water is the one length that is already known. Without it the depression angle fixes only a direction, never a distance.');

  /* uncertainty wedge */
  var dLo = null, dHi = null;
  if (e > 0) {
    dLo = L / Math.tan(rad(Math.min(alpha + e, 89.99)));
    dHi = L / Math.tan(rad(Math.max(alpha - e, 0.015)));
    var xLo = GX + dpxOf(clamp(dLo, 50, 3000)), xHi = GX + dpxOf(clamp(dHi, 50, 3000));
    wedgeBar([xLo, GY], [xHi, GY], [[GX, eY]]);
    gWedge.line(xLo, GY - 12, xLo, GY + 12).stroke({ color: ORANGE, width: 3 });
    gWedge.line(xHi, GY - 12, xHi, GY + 12).stroke({ color: ORANGE, width: 3 });
  }

  /* geometry */
  var rayEnd = (eY > GY - 150) ? Math.min(892, bx - 70) : 892;
  gGeo.line(GX + 22, eY, rayEnd, eY).stroke({ color: INK, width: 2.5 });
  gGeo.line(GX, eY, bx, GY).stroke({ color: INK, width: 3.2 });
  gGeo.line(GX, eY + 20, GX, GY).stroke({ color: INK, width: 3.2 });
  gGeo.polygon(GX + ',' + (GY - 20) + ' ' + (GX + 20) + ',' + (GY - 20) + ' ' + (GX + 20) + ',' + GY + ' ' + GX + ',' + GY)
    .fill('#c9c9c9').stroke({ color: INK, width: 2 });
  gGeo.line(GX, GY, bx, GY).stroke({ color: INK, width: 3.6 });

  var vx = bx - GX, vy = GY - eY, len = Math.hypot(vx, vy);
  var r1 = clamp(0.34 * len, 62, 112);
  var A1 = arcInfo(GX, eY, r1, 1, 0, vx, vy);
  gGeo.path(A1.path).fill('none').stroke({ color: INK, width: 2.8 });
  var r2 = clamp(0.22 * len, 42, 72);
  var A2 = arcInfo(bx, GY, r2, -1, 0, GX - bx, eY - GY);
  gGeo.path(A2.path).fill('none').stroke({ color: INK, width: 2.8 });

  gGeo.circle(36).center(GX, eY).fill('#fff').stroke({ color: INK, width: 3.6 });

  /* hover targets */
  hit(GX + 22, eY, rayEnd, eY, 'Horizontal reference: sight line to the horizon', 'A free horizontal',
    'Because the horizon is level with a distant sea surface, sighting it gives a horizontal reference line without any instrument. The boat sits α below it.');
  hit(GX, eY, bx, GY, 'Line of sight to the boat', 'The hypotenuse',
    'The sight line, the vertical height and the water surface close one right triangle, so tan α = h / d and therefore d = h / tan α.');
  hit(GX, eY, GX, GY, 'Known height h = ' + L + ' m', 'The known length h',
    'h is the only measured length in the whole construction. Double it and the same boat produces a larger, easier-to-measure α; forget it and α means nothing metric at all.');
  hit(GX, GY, bx, GY, 'd — the unknown horizontal distance', 'The unknown d',
    'This leg is what we want. Solving the right triangle gives d = h / tan α, so a small error in α turns into a large error in d whenever α is small.');
  hov(gGeo.circle(40).center(GX, eY).fill('#fff').opacity(0).attr('pointer-events', 'all'),
    "Observer's eye, h = " + L + ' m above the water', 'The observer',
    'One eye, one known height, one measured angle — enough to convert a direction into a distance.');

  /* labels */
  lab(GX - 32, (eY + GY) / 2, 'h');
  lab(GX + 0.45 * (bx - GX), GY + 36, 'd ?');
  lab(GX + (r1 + 30) * Math.cos(rad(A1.mid)), eY + (r1 + 30) * Math.sin(rad(A1.mid)), 'α');
