/* ───────── readout panel + true-scale inset ───────── */
function panel(formula, lines, insetFn) {
  var n = lines.length, bw = 434, bx = 558, bh = 40 + n * 24 + 22, by = 652 - bh;
  var box = gPanel.rect(bw, bh).move(bx, by).radius(6)
    .fill({ color: '#ffffff', opacity: 0.95 }).stroke({ color: '#888', width: 1.6 });
  hov(box, 'What is known, what is measured, what is inferred', 'Reading the numbers',
    'The first line is the active formula, then the one known length, then the measured angle(s), then the inferred distance. Non-zero measurement error adds the interval of distances that the same reading would allow.');
  gPanel.plain(formula).font({ family: SERIF, size: 23, anchor: 'start', style: 'italic' })
    .attr({ x: bx + 16, y: by + 30, fill: '#111', 'dominant-baseline': 'middle' });
  for (var i = 0; i < lines.length; i++) {
    gPanel.plain(lines[i]).font({ family: SERIF, size: 19, anchor: 'start' })
      .attr({ x: bx + 16, y: by + 56 + i * 24, fill: '#111', 'dominant-baseline': 'middle' });
  }
  gPanel.plain('sketch exaggerated · inset is true scale').font({ family: 'sans-serif', size: 13, anchor: 'start', style: 'italic' })
    .attr({ x: bx + 16, y: by + bh - 12, fill: '#777', 'dominant-baseline': 'middle' });
  if (insetFn) insetFn(gPanel, bx + 252, by + 26, 170, bh - 48);
}

function insetFrame(g, ax, ay, aw, ah, tip) {
  var r = g.rect(aw, ah).move(ax, ay).radius(4).fill('#fbfbfb').stroke({ color: '#ccc', width: 1 });
  hov(r, tip, 'True proportions',
    'The main sketch stretches the angles so the construction is readable. This inset draws the same triangle strictly to scale: the real angle is usually a thin sliver, which is exactly why a known length must be long compared with the range.');
  g.plain('true scale').font({ family: 'sans-serif', size: 13, anchor: 'middle' })
    .attr({ x: ax + aw / 2, y: ay + 13, fill: '#777', 'dominant-baseline': 'middle' });
}

function insetTri(g, ax, ay, aw, ah, L, d, note) {
  insetFrame(g, ax, ay, aw, ah, 'True shape of the h–d triangle');
  var ox = ax + 14, oy = ay + ah - 26;
  var s = Math.min((aw - 34) / d, Math.max(8, ah - 58) / L);
  var b = d * s, ht = L * s;
  g.line(ox, oy, ox + b, oy).stroke({ color: '#444', width: 1.6 });
  g.line(ox, oy, ox, oy - ht).stroke({ color: '#444', width: 1.6 });
  g.line(ox, oy - ht, ox + b, oy).stroke({ color: '#c0392b', width: 1.8 });
  g.plain(note).font({ family: SERIF, size: 14, anchor: 'end' })
    .attr({ x: ax + aw - 10, y: ay + ah - 10, fill: '#333', 'dominant-baseline': 'middle' });
}

function insetBase(g, ax, ay, aw, ah, t, d, note) {
  insetFrame(g, ax, ay, aw, ah, 'True shape of the baseline triangle');
  var s = Math.min((aw - 34) / d, Math.max(8, ah - 58) / t);
  var x0 = ax + 14, y0 = ay + 24;
  var y1 = y0 + t * s, px = x0 + d * s, py = y0 + FA * t * s;
  g.line(x0, y0, x0, y1).stroke({ color: '#444', width: 2.2 });
  g.line(x0, y0, px, py).stroke({ color: '#c0392b', width: 1.5 });
  g.line(x0, y1, px, py).stroke({ color: '#c0392b', width: 1.5 });
  g.plain(note).font({ family: SERIF, size: 14, anchor: 'end' })
    .attr({ x: ax + aw - 10, y: ay + ah - 10, fill: '#333', 'dominant-baseline': 'middle' });
}

