/* ───────── uncertainty wedge ───────── */
function wedgeBar(p1, p2, apexes) {
  for (var i = 0; i < apexes.length; i++) {
    gWedge.polygon(apexes[i][0] + ',' + apexes[i][1] + ' ' + p1[0] + ',' + p1[1] + ' ' + p2[0] + ',' + p2[1])
      .fill({ color: ORANGE, opacity: 0.20 }).stroke({ color: ORANGE, width: 1.4, opacity: 0.5 });
  }
  var bar = gWedge.line(p1[0], p1[1], p2[0], p2[1])
    .stroke({ color: ORANGE, width: 9, opacity: 0.9, linecap: 'butt' });
  hov(bar, 'Possible boat positions for the measured angle ±' + state.err + '°',
    'Angle error becomes distance error',
    'Every point in the orange wedge fits the measurement. Its length grows roughly with the square of the distance and shrinks in proportion to the known length h or t — the precision law of every angle-based rangefinder, including stereo vision.');
}

/* ───────── mode A: height + horizon ───────── */
function renderA() {
  var L = state.L, d = state.d, e = state.err;
  var hp = hpxOf(L), eY = GY - hp, bx = GX + dpxOf(d);
  var alpha = dg(Math.atan(L / d));

  sky();
  coastline([[210, HOR], [248, 316], [224, 364], [292, 410], [270, 460], [344, 512], [380, 572], [424, 626], [442, 660]]);
