      wl = [0, 16, -12, 18, -10, 20, -8, 10, 0], wr = [0, -14, 16, -10, 18, -12, 14, 8, 0];
  var pts = [], i, k;
  for (i = 0; i < ks.length; i++) { k = ks[i]; pts.push([GX - (150 * (1 - k) + wl[i] * (1 - k)), base - k * Ht]); }
  for (i = ks.length - 2; i >= 0; i--) { k = ks[i]; pts.push([GX + (158 * (1 - k) + wr[i] * (1 - k)), base - k * Ht]); }
  var cliff = gBg.path(smooth(pts) + ' Z').fill(CLIFF).stroke({ color: INK, width: 4, linejoin: 'round' });
  hov(cliff, 'The cliff — it supplies the known height h', 'Where the known length comes from',
    'The cliff is not decoration: its height above the water is the one length that is already known. Without it the depression angle fixes only a direction, never a distance.');

  /* uncertainty wedge */
  var dLo = null, dHi = null;
  if (e > 0) {
    dLo = L / Math.tan(rad(Math.min(alpha + e, 89.99)));
    dHi = L / Math.tan(rad(Math.max(alpha - e, 0.015)));
    var xLo = GX + dpxOf(clamp(dLo, 50, 3000)), xHi = GX + dpxOf(clamp(dHi, 50, 3000));
    wedgeBar([xLo, GY], [xHi, GY], [[GX, eY]]);
    gWedge.line(xLo, GY - 12, xLo, GY + 12).stroke({ color: ORANGE, width: 3 });
