  /* geometry */
  var rayEnd = (eY > GY - 150) ? Math.min(892, bx - 70) : 892;
  gGeo.line(GX + 22, eY, rayEnd, eY).stroke({ color: INK, width: 2.5 });
  gGeo.line(GX, eY, bx, GY).stroke({ color: INK, width: 3.2 });
  gGeo.line(GX, eY + 20, GX, GY).stroke({ color: INK, width: 3.2 });
  gGeo.polygon(GX + ',' + (GY - 20) + ' ' + (GX + 20) + ',' + (GY - 20) + ' ' + (GX + 20) + ',' + GY + ' ' + GX + ',' + GY)
    .fill('#c9c9c9').stroke({ color: INK, width: 2 });
  gGeo.line(GX, GY, bx, GY).stroke({ color: INK, width: 3.6 });

  var vx = bx - GX, vy = GY - eY, len = Math.hypot(vx, vy);
  var r1 = clamp(0.34 * len, 62, 112);
  var A1 = arcInfo(GX, eY, r1, 1, 0, vx, vy);
  gGeo.path(A1.path).fill('none').stroke({ color: INK, width: 2.8 });
  var r2 = clamp(0.22 * len, 42, 72);
  var A2 = arcInfo(bx, GY, r2, -1, 0, GX - bx, eY - GY);
  gGeo.path(A2.path).fill('none').stroke({ color: INK, width: 2.8 });

  gGeo.circle(36).center(GX, eY).fill('#fff').stroke({ color: INK, width: 3.6 });

  /* hover targets */
  hit(GX + 22, eY, rayEnd, eY, 'Horizontal reference: sight line to the horizon', 'A free horizontal',
