  lab(GX + (r1 + 30) * Math.cos(rad(A1.mid)), eY + (r1 + 30) * Math.sin(rad(A1.mid)), 'α');
  lab(bx + (r2 + 28) * Math.cos(rad(A2.mid)), GY + (r2 + 28) * Math.sin(rad(A2.mid)), 'α');

