/* ───────── mode B: two stations ───────── */
function renderB() {
  var t = state.L, d = state.d, e = state.err;
  var ux = 0.196, uy = 0.98, nx = 0.98, ny = -0.196;
  var Lt = LtOf(t), Ld = LdOf(d);
  var Ax = 140, Ay = 300;
  var Bx = Ax + Lt * ux, By = Ay + Lt * uy;
  var Fx = Ax + FA * Lt * ux, Fy = Ay + FA * Lt * uy;
  var Px = Fx + Ld * nx, Py = Fy + Ld * ny;

  var aA = dg(Math.atan(d / (FA * t)));
  var aB = dg(Math.atan(d / ((1 - FA) * t)));

  sky();
  coastline([[105, HOR], [152, 312], [136, 358], [198, 404], [186, 452], [252, 508], [236, 568], [298, 628], [290, 660]]);
  horizon();

  var dLo = null, dHi = null;
  if (e > 0) {
    var aAh = Math.min(aA + e, 89.98), aBh = Math.min(aB + e, 89.98);
    var aAl = Math.max(aA - e, 0.05), aBl = Math.max(aB - e, 0.05);
    dHi = t / (cot(aAh) + cot(aBh));
    dLo = t / (cot(aAl) + cot(aBl));
    var LLo = LdOf(clamp(dLo, 50, 3000)), LHi = LdOf(clamp(dHi, 50, 3000));
    wedgeBar([Fx + LLo * nx, Fy + LLo * ny], [Fx + LHi * nx, Fy + LHi * ny], [[Ax, Ay], [Bx, By]]);
  }

  /* baseline, sight lines, perpendicular */
  gGeo.line(Ax, Ay, Bx, By).stroke({ color: INK, width: 3.4 });
  gGeo.line(Ax, Ay, Px, Py).stroke({ color: INK, width: 3.2 });
  gGeo.line(Bx, By, Px, Py).stroke({ color: INK, width: 3.2 });
  gGeo.line(Fx, Fy, Px, Py).stroke({ color: INK, width: 3 }).attr('stroke-dasharray', '11,7');

  var s = 18;
  gGeo.polygon(Fx + ',' + Fy + ' ' + (Fx + s * ux) + ',' + (Fy + s * uy) + ' ' +
    (Fx + s * ux + s * nx) + ',' + (Fy + s * uy + s * ny) + ' ' + (Fx + s * nx) + ',' + (Fy + s * ny))
    .fill('#c9c9c9').stroke({ color: INK, width: 2 });

  var rA = clamp(0.42 * Lt, 46, 84);
  var AA = arcInfo(Ax, Ay, rA, Bx - Ax, By - Ay, Px - Ax, Py - Ay);
  gGeo.path(AA.path).fill('none').stroke({ color: INK, width: 2.8 });
  var rB = clamp(0.36 * Lt, 42, 74);
  var AB = arcInfo(Bx, By, rB, Ax - Bx, Ay - By, Px - Bx, Py - By);
  gGeo.path(AB.path).fill('none').stroke({ color: INK, width: 2.8 });

  gGeo.circle(36).center(Ax, Ay).fill('#fff').stroke({ color: INK, width: 3.6 });
  gGeo.circle(36).center(Bx, By).fill('#fff').stroke({ color: INK, width: 3.6 });

  hit(Ax, Ay, Bx, By, 'Known baseline t = ' + t + ' m', 'The baseline t',
    'The separation of the two stations replaces the known height. Stretch it and the two sight lines cross at a wider angle, so the intersection — the boat — is far better localised. This is why eyes and stereo cameras are set apart.');
  hit(Ax, Ay, Px, Py, 'Bearing taken at station A', 'Two bearings, one point',
    'Each station measures only a direction. Two directions from two known points intersect at exactly one place, so no horizon and no absolute height are needed — only the one known length t.');
  hit(Bx, By, Px, Py, 'Bearing taken at station B', 'Two bearings, one point',
    'Each station measures only a direction. Two directions from two known points intersect at exactly one place, so no horizon and no absolute height are needed — only the one known length t.');
  hit(Fx, Fy, Px, Py, 'd — perpendicular distance from the baseline to the boat', 'The unknown d',
    'Dropping the perpendicular splits the baseline into d·cot α and d·cot β. Their sum is t, which rearranges directly into d = t / (cot α + cot β).');
  hov(gGeo.circle(42).center(Ax, Ay).fill('#fff').opacity(0).attr('pointer-events', 'all'),
    'Station A — α = ' + aA.toFixed(2) + '°', 'Station A', 'One of the two viewpoints. Only the separation between them has to be known.');
  hov(gGeo.circle(42).center(Bx, By).fill('#fff').opacity(0).attr('pointer-events', 'all'),
    'Station B — β = ' + aB.toFixed(2) + '°', 'Station B', 'One of the two viewpoints. Only the separation between them has to be known.');

  lab(Ax + FA * Lt * ux * 0.5 - 30 * nx, Ay + FA * Lt * uy * 0.5 - 30 * ny, 't');
  lab(Fx + 0.42 * Ld * nx - 32 * ux, Fy + 0.42 * Ld * ny - 32 * uy, 'd ?');
  lab(Ax + (rA + 28) * Math.cos(rad(AA.mid)), Ay + (rA + 28) * Math.sin(rad(AA.mid)), 'α');
  lab(Bx + (rB + 28) * Math.cos(rad(AB.mid)), By + (rB + 28) * Math.sin(rad(AB.mid)), 'β');

  boat(Px, Py);

  var lines = ['t = ' + t + ' m   (known baseline)',
               'α = ' + aA.toFixed(2) + '°   (station A)',
               'β = ' + aB.toFixed(2) + '°   (station B)',
               'd = t / (cot α + cot β) = ' + Math.round(d) + ' m'];
  if (e > 0) {
    lines.push('±' + e.toFixed(2) + '° → d = ' + Math.round(dLo) + ' … ' +
      (dHi > 4000 ? '∞' : Math.round(dHi)) + ' m');
  }
  panel('d = t / (cot α + cot β)', lines, function (g, ax, ay, aw, ah) {
    insetBase(g, ax, ay, aw, ah, t, d, 'γ = ' + (180 - aA - aB).toFixed(2) + '°');
  });
}

/* ───────── readout panel + true-scale inset ───────── */
function panel(formula, lines, insetFn) {
  var n = lines.length, bw = 434, bx = 558, bh = 40 + n * 24 + 22, by = 652 - bh;
  var box = gPanel.rect(bw, bh).move(bx, by).radius(6)
    .fill({ color: '#ffffff', opacity: 0.95 }).stroke({ color: '#888', width: 1.6 });
  hov(box, 'What is known, what is measured, what is inferred', 'Reading the numbers',
    'The first line is the active formula, then the one known length, then the measured angle(s), then the inferred distance. Non-zero measurement error adds the interval of distances that the same reading would allow.');
  gPanel.plain(formula).font({ family: SERIF, size: 23, anchor: 'start', style: 'italic' })
    .attr({ x: bx + 16, y: by + 30, fill: '#111', 'dominant-baseline': 'middle' });
  for (var i = 0; i < lines.length; i++) {
    gPanel.plain(lines[i]).font({ family: SERIF, size: 19, anchor: 'start' })
      .attr({ x: bx + 16, y: by + 56 + i * 24, fill: '#111', 'dominant-baseline': 'middle' });
  }
  gPanel.plain('sketch exaggerated · inset is true scale').font({ family: 'sans-serif', size: 13, anchor: 'start', style: 'italic' })
    .attr({ x: bx + 16, y: by + bh - 12, fill: '#777', 'dominant-baseline': 'middle' });
  if (insetFn) insetFn(gPanel, bx + 252, by + 26, 170, bh - 48);
}

function insetFrame(g, ax, ay, aw, ah, tip) {
  var r = g.rect(aw, ah).move(ax, ay).radius(4).fill('#fbfbfb').stroke({ color: '#ccc', width: 1 });
  hov(r, tip, 'True proportions',
    'The main sketch stretches the angles so the construction is readable. This inset draws the same triangle strictly to scale: the real angle is usually a thin sliver, which is exactly why a known length must be long compared with the range.');
  g.plain('true scale').font({ family: 'sans-serif', size: 13, anchor: 'middle' })
    .attr({ x: ax + aw / 2, y: ay + 13, fill: '#777', 'dominant-baseline': 'middle' });
}

function insetTri(g, ax, ay, aw, ah, L, d, note) {
  insetFrame(g, ax, ay, aw, ah, 'True shape of the h–d triangle');
  var ox = ax + 14, oy = ay + ah - 26;
  var s = Math.min((aw - 34) / d, Math.max(8, ah - 58) / L);
  var b = d * s, ht = L * s;
  g.line(ox, oy, ox + b, oy).stroke({ color: '#444', width: 1.6 });
  g.line(ox, oy, ox, oy - ht).stroke({ color: '#444', width: 1.6 });
  g.line(ox, oy - ht, ox + b, oy).stroke({ color: '#c0392b', width: 1.8 });
  g.plain(note).font({ family: SERIF, size: 14, anchor: 'end' })
    .attr({ x: ax + aw - 10, y: ay + ah - 10, fill: '#333', 'dominant-baseline': 'middle' });
}

function insetBase(g, ax, ay, aw, ah, t, d, note) {
  insetFrame(g, ax, ay, aw, ah, 'True shape of the baseline triangle');
  var s = Math.min((aw - 34) / d, Math.max(8, ah - 58) / t);
  var x0 = ax + 14, y0 = ay + 24;
  var y1 = y0 + t * s, px = x0 + d * s, py = y0 + FA * t * s;
  g.line(x0, y0, x0, y1).stroke({ color: '#444', width: 2.2 });
  g.line(x0, y0, px, py).stroke({ color: '#c0392b', width: 1.5 });
  g.line(x0, y1, px, py).stroke({ color: '#c0392b', width: 1.5 });
  g.plain(note).font({ family: SERIF, size: 14, anchor: 'end' })
    .attr({ x: ax + aw - 10, y: ay + ah - 10, fill: '#333', 'dominant-baseline': 'middle' });
}

/* ───────── render ───────── */
function render() {
  gBg.clear(); gWedge.clear(); gGeo.clear(); gBoat.clear(); gLab.clear(); gPanel.clear();
  if (state.mode2) renderB(); else renderA();
}

/* ───────── controls ───────── */
function toggle_methodToggle(on) {
  state.mode2 = !!on;
  document.getElementById('knownLabel').textContent = on ? 'Known baseline t (m)' : 'Known height h (m)';
  render();
}
function update_knownLength(v) { state.L = v; render(); }
function update_boatDistance(v) { state.d = v; render(); }
function update_angleError(v) { state.err = v; render(); }

/* ───────── demo steps ───────── */
var steps = [
  { title: 'How far away is the boat?',
    narration: 'A boat sits on the sea and we cannot walk out to it. Only angles can be measured from shore, so d is the unknown we must build out of geometry.',
    state: { methodToggle: 'Height + horizon', knownLength: 40, boatDistance: 600, angleError: 0 } },
  { title: 'The horizon supplies a horizontal reference',
    narration: 'Sighting the horizon gives an essentially horizontal line, so the angle α dipping below it is the depression angle to the boat. The same α reappears at the boat as an alternate angle, closing a right triangle with legs h and d.',
    state: { methodToggle: 'Height + horizon', knownLength: 40, boatDistance: 600, angleError: 0 } },
  { title: 'Height sets the scale: d = h / tan α',
    narration: 'Climb higher and α grows for the very same boat. The known height is what turns an angle into metres — with h unknown, α by itself says nothing about distance.',
    state: { methodToggle: 'Height + horizon', knownLength: 160, boatDistance: 600, angleError: 0 } },
  { title: 'Far boats squeeze the angle shut',
    narration: 'Send the boat out to sea and α collapses onto the horizon: watch the true-scale inset flatten to a sliver. Distant objects differ by fractions of a degree, which is why far distances are hardest to pin down.',
    state: { methodToggle: 'Height + horizon', knownLength: 40, boatDistance: 2600, angleError: 0 } },
  { title: 'Trade the height for a baseline',
    narration: 'Two shore stations a known distance t apart each take a bearing, α and β. The boat lies where the two sight lines cross — no horizon and no height required, but the same single known length.',
    state: { methodToggle: 'Two stations', knownLength: 40, boatDistance: 600, angleError: 0 } },
  { title: 'A longer baseline gives a sharper fix',
    narration: 'Stretch t and the two sight lines meet at a wider angle, so their intersection is far better localised. Add error and the uncertainty wedge at the boat visibly narrows.',
    state: { methodToggle: 'Two stations', knownLength: 220, boatDistance: 600, angleError: 0 } },
  { title: 'Angle error becomes distance error',
    narration: 'Give each measurement a small error and watch the orange wedge at the boat. The same half-degree is harmless close in and enormous far out, and shrinks again whenever h or t is increased.',
    state: { methodToggle: 'Two stations', knownLength: 40, boatDistance: 2200, angleError: 1 } }
];
var cur = 0;

function setSlider(id, v) {
  var i = document.getElementById(id + 'Input'); if (i) i.value = v;
  var o = document.getElementById(id + 'Val'); if (o) o.value = v;
}
function applyState(st) {
  if ('methodToggle' in st) {
    var on = /Two/.test(st.methodToggle);
    document.getElementById('methodToggleInput').checked = on;
    state.mode2 = on;
    document.getElementById('knownLabel').textContent = on ? 'Known baseline t (m)' : 'Known height h (m)';
  }
  if ('knownLength' in st) { setSlider('knownLength', st.knownLength); state.L = +st.knownLength; }
  if ('boatDistance' in st) { setSlider('boatDistance', st.boatDistance); state.d = +st.boatDistance; }
  if ('angleError' in st) { setSlider('angleError', st.angleError); state.err = +st.angleError; }
  render();
}
function gotoStep(i) {
  cur = clamp(i, 0, steps.length - 1);
  var s = steps[cur];
  document.getElementById('demoNarration').innerHTML = '<b>' + s.title + '</b><br>' + s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
  applyState(s.state);
}
function prevStep() { gotoStep(cur - 1); }
function nextStep() { gotoStep(cur + 1); }

gotoStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

