<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:bold;font-size:13px">How far is the boat?</span>
<span id="demoNarration" style="display:block;line-height:1.45;min-height:92px"></span>
<span style="display:flex;gap:6px;align-items:center">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="flex:1;text-align:center"></span>
  <button onclick="nextStep()">▶</button>
</span>
<span style="display:block;height:1px;background:#ddd;margin:4px 0"></span>
<label>Focus
  <select id="methodFocusInput" onchange="toggle_methodFocus(this.value)">
    <option value="Both panels">Both panels</option>
    <option value="Height + horizon (d = h / tan α)">Left — height + horizon</option>
    <option value="Two stations (d = t / (cot α + cot β))">Right — two stations</option>
  </select>
</label>
<label>Known length — h (left) &amp; t (right), m: <output id="knownLengthVal">40</output>
  <input id="knownLengthInput" type="range" min="5" max="250" step="5" value="40" oninput="document.getElementById('knownLengthVal').value=this.value;update_knownLength(+this.value)"></label>
<label>True boat distance d (m): <output id="boatDistanceVal">600</output>
  <input id="boatDistanceInput" type="range" min="50" max="3000" step="10" value="600" oninput="document.getElementById('boatDistanceVal').value=this.value;update_boatDistance(+this.value)"></label>
<label>Angle measurement error (°): <output id="angleErrorVal">0</output>
  <input id="angleErrorInput" type="range" min="0" max="2" step="0.05" value="0" oninput="document.getElementById('angleErrorVal').value=this.value;update_angleError(+this.value)"></label>
<span style="display:block;color:#666;line-height:1.4;margin-top:2px">Angles alone never give a distance — you always need one <i>known length</i>: a height h or a baseline t. Both sketches are drawn in exaggerated perspective (see the note under each panel). Hover or click the eye, the cliff, the stations, the boats or the orange wedge.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var W = 1600, H = 574, PW = 780, PH = 520, PY = 8, PX1 = 8, PX2 = 812, HOR = 219;
var SEA = '#5CF5E2', LAND = '#C4820C', CLIFF = '#8A4A07', ORANGE = '#F04A10', INK = '#000';
var SERIF = 'Georgia,"Times New Roman",serif';
var FA = 0.55;

var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);
var main = draw.group();

var state = { focus: 'both', L: 40, d: 600, err: 0 };

/* ── math helpers ── */
function rad(a) { return a * Math.PI / 180; }
function dg(r) { return r * 180 / Math.PI; }
function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function cot(deg) { return 1 / Math.tan(rad(deg)); }
function unit(x, y) { var m = Math.hypot(x, y) || 1; return [x / m, y / m]; }

/* ── sketch mappings ── */
function obsYof(h) { return 200 - 130 * Math.pow(clamp((h - 5) / 245, 0, 1), 0.45); }
function lenL(d) { return 250 + 350 * Math.pow(clamp((d - 50) / 2950, 0, 1), 0.30); }
function lenT(t) { return 220 + 95 * Math.sqrt(clamp((t - 5) / 245, 0, 1)); }
function lenD(d) { return 230 + 200 * Math.pow(clamp((d - 50) / 2950, 0, 1), 0.30); }
function boatScale(d) { return 1.25 - 0.25 * clamp((d - 50) / 2950, 0, 1); }

var FOOT = [135, 426], UL = unit(451, -96);
var AST = [118, 248], UB = unit(0.651, 0.759), ND = unit(0.99, -0.14), P0 = [210, 355];

/* ── drawing helpers ── */
function hov(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (title) el.on('click', function () { showPopup(title, body); });
  return el;
}
function labTxt(g, x, y, s, size) {
  var t = g.plain(s).font({ family: SERIF, size: size || 42, anchor: 'middle', style: 'italic' });
  t.attr({
    x: x, y: y, 'dominant-baseline': 'middle', fill: INK,
    'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 7, 'stroke-linejoin': 'round'
  });
  return t;
}
function hit(g, x1, y1, x2, y2, tip, title, body) {
  var e = g.line(x1, y1, x2, y2).stroke({ color: '#000', width: 26, opacity: 0 })
    .attr('pointer-events', 'stroke');
  return hov(e, tip, title, body);
}
function smooth(pts) {
  var d = 'M' + pts[0][0] + ',' + pts[0][1], n = pts.length;
  for (var i = 0; i < n - 1; i++) {
    var p0 = pts[i - 1 < 0 ? 0 : i - 1], p1 = pts[i], p2 = pts[i + 1], p3 = pts[i + 2 > n - 1 ? n - 1 : i + 2];
    d += ' C' + (p1[0] + (p2[0] - p0[0]) / 6) + ',' + (p1[1] + (p2[1] - p0[1]) / 6) + ' ' +
      (p2[0] - (p3[0] - p1[0]) / 6) + ',' + (p2[1] - (p3[1] - p1[1]) / 6) + ' ' + p2[0] + ',' + p2[1];
  }
  return d;
}
function arcInfo(cx, cy, r, ax, ay, bx, by) {
  var a0 = dg(Math.atan2(ay, ax)), a1 = dg(Math.atan2(by, bx));
  var diff = ((a1 - a0 + 540) % 360) - 180, t1 = a0 + diff;
  var x0 = cx + r * Math.cos(rad(a0)), y0 = cy + r * Math.sin(rad(a0));
  var x1 = cx + r * Math.cos(rad(t1)), y1 = cy + r * Math.sin(rad(t1));
  return {
    path: 'M' + x0 + ',' + y0 + ' A' + r + ',' + r + ' 0 0 ' + (diff > 0 ? 1 : 0) + ' ' + x1 + ',' + y1,
    mid: a0 + diff / 2, span: Math.abs(diff)
  };
}
function angBetween(v1, v2) {
  var a = Math.atan2(v1[1], v1[0]), b = Math.atan2(v2[1], v2[0]);
  var d = Math.abs(dg(b - a)) % 360;
  return d > 180 ? 360 - d : d;
}

/* ── scenery ── */
function scenery(g, shore) {
  g.rect(PW, PH).fill('#fff');
  g.rect(PW, PH - HOR).move(0, HOR).fill(SEA);
  var sd = smooth(shore);
  g.path(sd + ' L0,' + PH + ' L0,' + HOR + ' Z').fill(LAND).stroke('none');
  g.path(sd).fill('none').stroke({ color: INK, width: 4.5, linecap: 'round' });
  var hl = g.line(0, HOR, PW, HOR).stroke({ color: INK, width: 4 });
  hov(hl, 'Horizon — the sky / sea boundary', 'The horizon',
    'A sight line to the horizon is essentially horizontal, which hands the single observer a free horizontal reference to measure the depression angle α against. The two-station method needs no horizon at all.');
}

function boat(g, x, y, s, tip) {
  var b = g.group().attr('transform', 'translate(' + x + ',' + y + ') scale(' + s + ')');
  b.path('M-36,-6 L36,-6 C31,9 19,15 0,15 C-19,15 -31,9 -36,-6 Z')
    .fill('#fff').stroke({ color: INK, width: 3.2, linejoin: 'round' });
  b.line(-34, -2, 34, -2).stroke({ color: INK, width: 2.6 });
  b.line(4, -8, 7, -82).stroke({ color: INK, width: 3.2, linecap: 'round' });
  b.polygon('1,-78 1,-13 -33,-13').fill('#fff').stroke({ color: INK, width: 3.2, linejoin: 'round' });
  b.polygon('12,-66 12,-15 34,-15').fill('#fff').stroke({ color: INK, width: 3.2, linejoin: 'round' });
  hov(b, tip, 'The unknown',
    'The boat cannot be reached, so its distance has to be built out of angles. The slider sets the truth; each card shows what an observer could infer from the measured angle(s) plus the one length already known.');
  return b;
}

/* ── readout card ── */
function card(g, x, y, w, title, lines, titleSize) {
  var h = 44 + lines.length * 28 + 10;
  var box = g.rect(w, h).move(x, y).radius(8)
    .fill({ color: '#ffffff', opacity: 0.95 }).stroke({ color: '#3a3a3a', width: 2 });
  hov(box, 'Known length, measured angle(s), inferred distance', 'Reading the card',
    'The top line is the active formula, then the one length that must already be known, then the measured angle(s), then the distance those numbers imply. With a non-zero measurement error the last line gives the whole range of distances the same reading would allow.');
  g.plain(title).font({ family: SERIF, size: titleSize || 26, anchor: 'start', style: 'italic' })
    .attr({ x: x + 14, y: y + 28, fill: '#111', 'dominant-baseline': 'middle' });
  for (var i = 0; i < lines.length; i++) {
    g.plain(lines[i]).font({ family: SERIF, size: 23, anchor: 'start' })
      .attr({ x: x + 14, y: y + 58 + i * 28, fill: '#111', 'dominant-baseline': 'middle' });
  }
  return h;
}

/* ── uncertainty wedge ── */
function wedge(g, p1, p2, apexes, tip) {
  for (var i = 0; i < apexes.length; i++) {
    g.polygon(apexes[i][0] + ',' + apexes[i][1] + ' ' + p1[0] + ',' + p1[1] + ' ' + p2[0] + ',' + p2[1])
      .fill({ color: ORANGE, opacity: 0.20 }).stroke({ color: ORANGE, width: 1.6, opacity: 0.55 });
  }
  var bar = g.line(p1[0], p1[1], p2[0], p2[1])
    .stroke({ color: ORANGE, width: 11, opacity: 0.92, linecap: 'butt' });
  hov(bar, tip, 'Angle error becomes distance error',
    'Every point inside the orange wedge fits the measurement equally well. The band lengthens roughly with the square of the distance and shrinks in proportion to the known length h or t — the precision law behind every angle-based rangefinder, including your own two eyes.');
}

/* ── LEFT PANEL: height + horizon ── */
function drawLeft(g) {
  var h = state.L, d = state.d, e = state.err;
  var obsY = obsYof(h), Lp = lenL(d);
  var bx = FOOT[0] + Lp * UL[0], by = FOOT[1] + Lp * UL[1];
  var alpha = dg(Math.atan(h / d));

  scenery(g, [[170, HOR], [190, 250], [180, 278], [220, 300], [212, 330], [255, 358],
  [248, 392], [295, 425], [320, 455], [370, 487], [402, 506], [432, PH]]);

  /* twin-lobed headland */
  var apexY = obsY + 14, base = 445, Ht = base - apexY;
  var leftP = [[146, apexY], [128, apexY + 0.09 * Ht], [136, apexY + 0.20 * Ht], [112, apexY + 0.34 * Ht],
  [104, apexY + 0.50 * Ht], [78, apexY + 0.64 * Ht], [66, apexY + 0.78 * Ht], [34, apexY + 0.90 * Ht], [8, base]];
  var rightP = [[146, apexY], [163, apexY + 0.10 * Ht], [156, apexY + 0.24 * Ht], [180, apexY + 0.33 * Ht],
  [192, apexY + 0.48 * Ht], [183, apexY + 0.60 * Ht], [205, apexY + 0.72 * Ht], [212, apexY + 0.86 * Ht], [222, base]];
  var pts = [], i;
  for (i = leftP.length - 1; i >= 0; i--) pts.push(leftP[i]);
  for (i = 1; i < rightP.length; i++) pts.push(rightP[i]);
  var cliff = g.path(smooth(pts) + ' L8,' + base + ' Z')
    .fill(CLIFF).stroke({ color: INK, width: 4.5, linejoin: 'round' });
  hov(cliff, 'The headland — it supplies the known height h = ' + h + ' m', 'Where the known length comes from',
    'The cliff is not decoration: its height above the water is the one length that is already known. Without it the depression angle fixes only a direction, never a distance.');

  /* uncertainty wedge */
  var dLo = null, dHi = null;
  if (e > 0) {
    dLo = h / Math.tan(rad(Math.min(alpha + e, 89.98)));
    dHi = h / Math.tan(rad(Math.max(alpha - e, 0.01)));
    var lo = lenL(clamp(dLo, 50, 3000)), hi = lenL(clamp(dHi, 50, 3000));
    wedge(g, [FOOT[0] + lo * UL[0], FOOT[1] + lo * UL[1]],
      [FOOT[0] + hi * UL[0], FOOT[1] + hi * UL[1]], [[135, obsY]],
      'Possible boat positions for α ± ' + e.toFixed(2) + '°');
  }

  /* geometry */
  var rayEnd = 440;
  g.line(153, obsY, rayEnd, obsY).stroke({ color: INK, width: 3 });
  g.line(135, obsY, bx, by).stroke({ color: INK, width: 3.6 });
  g.line(135, obsY + 18, FOOT[0], FOOT[1]).stroke({ color: INK, width: 3.6 });
  g.line(FOOT[0], FOOT[1], bx, by).stroke({ color: INK, width: 4 });
  var s = 21;
  g.polygon(FOOT[0] + ',' + FOOT[1] + ' ' + FOOT[0] + ',' + (FOOT[1] - s) + ' ' +
    (FOOT[0] + s * UL[0]) + ',' + (FOOT[1] - s + s * UL[1]) + ' ' +
    (FOOT[0] + s * UL[0]) + ',' + (FOOT[1] + s * UL[1]))
    .fill('#c9c9c9').stroke({ color: INK, width: 2 });

  var v = [bx - 135, by - obsY], len = Math.hypot(v[0], v[1]);
  var r1 = clamp(0.26 * len, 80, 120);
  var A1 = arcInfo(135, obsY, r1, 1, 0, v[0], v[1]);
  g.path(A1.path).fill('none').stroke({ color: INK, width: 3 });
  var r2 = clamp(0.17 * len, 62, 92);
  var A2 = arcInfo(bx, by, r2, -UL[0], -UL[1], 135 - bx, obsY - by);
  g.path(A2.path).fill('none').stroke({ color: INK, width: 3 });

  g.circle(40).center(135, obsY).fill('#fff').stroke({ color: INK, width: 4 });

  /* hover targets */
  hit(g, 153, obsY, rayEnd, obsY, 'Horizontal reference: the sight line to the horizon', 'A free horizontal',
    'Because a distant sea surface is level with the eye, sighting the horizon gives a horizontal reference without any instrument. The boat sits α below that line.');
  hit(g, 135, obsY, bx, by, 'Line of sight to the boat', 'The hypotenuse',
    'The sight line, the vertical height and the water surface close one right triangle, so tan α = h / d and therefore d = h / tan α.');
  hit(g, 135, obsY + 18, FOOT[0], FOOT[1], 'Known height h = ' + h + ' m', 'The known length h',
    'h is the only measured length in the whole construction. Raise it and the same boat gives a larger, easier-to-measure α; drop it and α carries no metric information at all.');
  hit(g, FOOT[0], FOOT[1], bx, by, 'd — the unknown distance across the water', 'The unknown d',
    'This leg is what we want. Solving the right triangle gives d = h / tan α, so a small error in α turns into a large error in d whenever α is small.');
  hov(g.circle(46).center(135, obsY).fill('#fff').opacity(0).attr('pointer-events', 'all'),
    "Observer's eye, h = " + h + ' m above the water', 'The observer',
    'One eye, one known height, one measured angle — enough to convert a direction into a distance.');

  boat(g, bx, by, boatScale(d), 'Boat — true distance d = ' + d + ' m');

  labTxt(g, 108, (obsY + FOOT[1]) / 2, 'h');
  var bm = [(FOOT[0] + bx) / 2, (FOOT[1] + by) / 2];
  labTxt(g, bm[0] - 6 - 26 * UL[1] * -1 * 0 - 6, bm[1] - 28, 'd ?');
  labTxt(g, 135 + (r1 + 26) * Math.cos(rad(A1.mid)), obsY + (r1 + 26) * Math.sin(rad(A1.mid)), 'α');
  labTxt(g, bx + (r2 + 24) * Math.cos(rad(A2.mid)), by + (r2 + 24) * Math.sin(rad(A2.mid)), 'α');

  var lines = ['h = ' + h + ' m  (known)', 'α = ' + alpha.toFixed(2) + '°  (measured)',
    'd = h / tan α = ' + Math.round(d) + ' m'];
  if (e > 0) {
    lines.push('± ' + e.toFixed(2) + '° → d = ' + Math.round(dLo) + '…' +
      (dHi > 20000 ? '∞' : Math.round(dHi)) + ' m');
  }
  card(g, 455, 14, 302, 'd = h / tan α', lines);

  return { drawn: dg(Math.atan((by - obsY) / (bx - 135))), alpha: alpha, mpp: d / Lp };
}

/* ── RIGHT PANEL: two stations ── */
function drawRight(g) {
  var t = state.L, d = state.d, e = state.err;
  var Lt = lenT(t);
  var Bx = AST[0] + Lt * UB[0], By = AST[1] + Lt * UB[1];
  var Fx = AST[0] + FA * Lt * UB[0], Fy = AST[1] + FA * Lt * UB[1];
  var Ld = lenD(d), Px = P0[0] + Ld * ND[0], Py = P0[1] + Ld * ND[1];
  var aA = dg(Math.atan(d / (FA * t))), aB = dg(Math.atan(d / ((1 - FA) * t)));

  scenery(g, [[185, HOR], [205, 250], [196, 278], [235, 300], [226, 330], [268, 360],
  [258, 398], [300, 430], [325, 462], [372, 492], [404, 510], [436, PH]]);

  var dLo = null, dHi = null;
  if (e > 0) {
    dHi = t / (cot(Math.min(aA + e, 89.98)) + cot(Math.min(aB + e, 89.98)));
    dLo = t / (cot(Math.max(aA - e, 0.05)) + cot(Math.max(aB - e, 0.05)));
    var l1 = lenD(clamp(dLo, 50, 3000)), l2 = lenD(clamp(dHi, 50, 3000));
    wedge(g, [P0[0] + l1 * ND[0], P0[1] + l1 * ND[1]], [P0[0] + l2 * ND[0], P0[1] + l2 * ND[1]],
      [[AST[0], AST[1]], [Bx, By]], 'Possible boat positions for α, β ± ' + e.toFixed(2) + '°');
  }

  g.line(AST[0], AST[1], Bx, By).stroke({ color: INK, width: 3.8 });
  g.line(AST[0], AST[1], Px, Py).stroke({ color: INK, width: 3.4 });
  g.line(Bx, By, Px, Py).stroke({ color: INK, width: 3.4 });
  var nd = unit(Px - Fx, Py - Fy);
  g.line(Fx, Fy, Px, Py).stroke({ color: INK, width: 3 }).attr('stroke-dasharray', '12,8');

  var s = 20;
  g.polygon(Fx + ',' + Fy + ' ' + (Fx + s * UB[0]) + ',' + (Fy + s * UB[1]) + ' ' +
    (Fx + s * UB[0] + s * nd[0]) + ',' + (Fy + s * UB[1] + s * nd[1]) + ' ' +
    (Fx + s * nd[0]) + ',' + (Fy + s * nd[1]))
    .fill('#c9c9c9').stroke({ color: INK, width: 2 });

  var rA = clamp(0.30 * Lt, 62, 92);
  var AA = arcInfo(AST[0], AST[1], rA, Bx - AST[0], By - AST[1], Px - AST[0], Py - AST[1]);
  g.path(AA.path).fill('none').stroke({ color: INK, width: 3 });
  var rB = clamp(0.26 * Lt, 54, 80);
  var AB = arcInfo(Bx, By, rB, AST[0] - Bx, AST[1] - By, Px - Bx, Py - By);
  g.path(AB.path).fill('none').stroke({ color: INK, width: 3 });

  g.circle(40).center(AST[0], AST[1]).fill('#fff').stroke({ color: INK, width: 4 });
  g.circle(40).center(Bx, By).fill('#fff').stroke({ color: INK, width: 4 });

  hit(g, AST[0], AST[1], Bx, By, 'Known baseline t = ' + t + ' m', 'The baseline t',
    'The separation of the two stations replaces the known height. Stretch it and the two sight lines cross at a wider angle, so the intersection — the boat — is far better localised. This is exactly why eyes and stereo cameras are set apart.');
  hit(g, AST[0], AST[1], Px, Py, 'Bearing taken at station A  (α = ' + aA.toFixed(2) + '°)', 'Two bearings, one point',
    'Each station measures only a direction. Two directions from two known points intersect at exactly one place, so no horizon and no absolute height are needed — only the one known length t.');
  hit(g, Bx, By, Px, Py, 'Bearing taken at station B  (β = ' + aB.toFixed(2) + '°)', 'Two bearings, one point',
    'Each station measures only a direction. Two directions from two known points intersect at exactly one place, so no horizon and no absolute height are needed — only the one known length t.');
  hit(g, Fx, Fy, Px, Py, 'd — distance from the baseline out to the boat', 'The unknown d',
    'Dropping the perpendicular splits the baseline into d·cot α and d·cot β. Their sum is t, which rearranges straight into d = t / (cot α + cot β).');
  hov(g.circle(46).center(AST[0], AST[1]).fill('#fff').opacity(0).attr('pointer-events', 'all'),
    'Station A — α = ' + aA.toFixed(2) + '°', 'Station A',
    'One of two viewpoints. Neither station needs to know its height above the sea; only the distance between them must be known.');
  hov(g.circle(46).center(Bx, By).fill('#fff').opacity(0).attr('pointer-events', 'all'),
    'Station B — β = ' + aB.toFixed(2) + '°', 'Station B',
    'One of two viewpoints. Neither station needs to know its height above the sea; only the distance between them must be known.');

  boat(g, Px, Py, boatScale(d), 'Boat — true distance d = ' + d + ' m');

  labTxt(g, (AST[0] + Fx) / 2 - 36, (AST[1] + Fy) / 2 + 30, 't');
  labTxt(g, Fx + 0.62 * (Px - Fx), Fy + 0.62 * (Py - Fy) + 34, 'd ?');
  labTxt(g, AST[0] + (rA + 26) * Math.cos(rad(AA.mid)), AST[1] + (rA + 26) * Math.sin(rad(AA.mid)), 'α');
  labTxt(g, Bx + (rB + 26) * Math.cos(rad(AB.mid)), By + (rB + 26) * Math.sin(rad(AB.mid)), 'β');

  var lines = ['t = ' + t + ' m  (known baseline)',
  'α = ' + aA.toFixed(2) + '°,  β = ' + aB.toFixed(2) + '°',
  'd = ' + Math.round(d) + ' m  (inferred)'];
  if (e > 0) {
    lines.push('± ' + e.toFixed(2) + '° → d = ' + Math.round(dLo) + '…' +
      (dHi > 20000 ? '∞' : Math.round(dHi)) + ' m');
  }
  card(g, 418, 14, 342, 'd = t / (cot α + cot β)', lines, 25);

  return {
    drawnA: angBetween([Bx - AST[0], By - AST[1]], [Px - AST[0], Py - AST[1]]),
    aA: aA, aB: aB, mpp: d / Ld
  };
}

/* ── render ── */
function render() {
  main.clear();
  var gL = main.group().attr('transform', 'translate(' + PX1 + ',' + PY + ')');
  var sL = drawLeft(gL);
  var gR = main.group().attr('transform', 'translate(' + PX2 + ',' + PY + ')');
  var sR = drawRight(gR);

  if (state.focus === 'right') { gL.opacity(0.20); gL.attr('pointer-events', 'none'); }
  if (state.focus === 'left') { gR.opacity(0.20); gR.attr('pointer-events', 'none'); }

  gL.rect(PW, PH).fill('none').stroke({ color: INK, width: 9 });
  gR.rect(PW, PH).fill('none').stroke({ color: INK, width: 9 });

  var nL = 'Left — exaggerated perspective: true α = ' + sL.alpha.toFixed(2) +
    '°, drawn ≈ ' + sL.drawn.toFixed(0) + '°;  scale ≈ ' + sL.mpp.toFixed(1) + ' m per unit.';
  var nR = 'Right — exaggerated perspective: true α = ' + sR.aA.toFixed(1) + '°, β = ' + sR.aB.toFixed(1) +
    '°, drawn ≈ ' + sR.drawnA.toFixed(0) + '°;  scale ≈ ' + sR.mpp.toFixed(1) + ' m per unit.';
  main.plain(nL).font({ family: 'sans-serif', size: 19, anchor: 'start' })
    .attr({ x: PX1 + 6, y: PY + PH + 30, fill: '#555', 'dominant-baseline': 'middle' });
  main.plain(nR).font({ family: 'sans-serif', size: 19, anchor: 'start' })
    .attr({ x: PX2 + 6, y: PY + PH + 30, fill: '#555', 'dominant-baseline': 'middle' });
}

/* ── controls ── */
function toggle_methodFocus(v) {
  state.focus = /Two/.test(v) ? 'right' : (/Height/.test(v) ? 'left' : 'both');
  render();
}
function update_knownLength(v) { state.L = v; render(); }
function update_boatDistance(v) { state.d = v; render(); }
function update_angleError(v) { state.err = v; render(); }

